            rightReference = new DataGridViewTextBoxColumn();
            rightPick = new DataGridViewButtonColumn();
            SuspendLayout();
            layout.Name = "layout";
            layout.Dock = DockStyle.Fill;
            layout.ColumnCount = 1;
